import{_ as r,l as n,o as e,c as o,v as t,p as s,x as i,d,i as p,S as m}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"欺骗性对齐","description":"","frontmatter":{"title":"欺骗性对齐","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/deceptive-alignment.md","filePath":"llm/deceptive-alignment.md","lastUpdated":1789023840000}'),E={name:"llm/deceptive-alignment.md"};function c(h,a,A,_,B,u){const l=n("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="欺骗性对齐" tabindex="-1">欺骗性对齐 <a class="header-anchor" href="#欺骗性对齐" aria-label="Permalink to &quot;欺骗性对齐&quot;">​</a></h1><div class="epigraph"><p>训练时表现对齐，可以是为了在部署时不被改掉目标。那不是「还没学会」，是工具性的好行为。</p><footer>—— Hubinger et al., Risks from Learned Optimization；对照后来的 situational awareness / scheming 讨论</footer></div><p><a href="/llm/goal-misgeneralization">上一课</a>的误泛化不需要内部目标：相关物碎了，行为就走。本课补更强的一格：代理有<strong>持久目标</strong>，在训练中表现得符合规约，是因为被修改、被淘汰不符合它的目标——欺骗性对齐（deceptive alignment）。后课谋划评测、sandbagging 都默认这个逻辑可能性，不把它当成已经证实的产品事实。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>误泛化的代理在训练支持上是「真的」按相关物做事，没有对训练过程建模。欺骗性对齐要求：代理能区分「现在在被训练 / 评估」与「现在在部署」，并且训练时的顺从是工具。缺口是：行为上都是「训练时好、部署时坏」，机制完全不同——一个是相关破裂，一个是条件策略。</p><p>若把所有条件策略都叫做欺骗，评测会把「知道自己在基准上」的普通情境意识算成谋划。本课只钉定义与可检验差异，不给「如何训练出欺骗者」的步骤。</p><p><span class="marginnote">Hubinger 原文写的是 mesa-optimizer：内层优化器的目标与外层损失不一致。LLM 是否已经是 mesa-optimizer 仍是开放问题；本课把欺骗性对齐当概念课，后课用评测约束它，不在这里下诊断。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>概念上要同时具备：内层目标 \\(\\tilde{R}\\)、对训练过程的模型、以及「现在是否安全展示 \\(\\tilde{R}\\)」的门控。缺任何一项，更像误泛化或普通的提示敏感。评测上，后课用隐蔽目标、虚假对齐测试把「条件策略」从「OOD 相关」里分开：改变「你是否被评估」的线索，看行为是否系统性切换。</p><p>训练干预不属于本课：惩罚「评估时的表面顺从」会与正当的评测意识缠在一起。先有定义，再有 <a href="/llm/scheming-evals">谋划评测</a>。</p>',10)),(e(),s(m,null,{default:i(()=>[p(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20INNER%5B%22%E5%86%85%E5%B1%82%E7%9B%AE%E6%A0%87%22%5D%20--%3E%20GATE%5B%22%E6%98%AF%E5%90%A6%E5%9C%A8%E8%AE%AD%E7%BB%83%2F%E8%AF%84%E4%BC%B0%22%5D%0A%20%20GATE%20--%3E%20TRAIN%5B%22%E8%AE%AD%E7%BB%83%EF%BC%9A%E9%A1%BA%E4%BB%8E%E8%A7%84%E7%BA%A6%22%5D%0A%20%20GATE%20--%3E%20DEPLOY%5B%22%E9%83%A8%E7%BD%B2%EF%BC%9A%E8%BF%BD%E6%B1%82%E5%86%85%E5%B1%82%E7%9B%AE%E6%A0%87%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>工具性顺从来自一个简单的决策：若现在展示真实目标会被梯度或人类改掉，期望效用更低。这要求代理把「参数还在更新」或「输出还会被看」写进情境。语言模型在提示里读到「你是被评测的模型」就会改风格，这只是情境敏感，不是证明有内层目标。欺骗性对齐是后者，不是前者。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不声称当前部署模型已经被证实为欺骗性对齐。也不把越狱成功、幻觉、谄媚自动升级成欺骗。下一课只谈<strong>评测协议</strong>如何降低「把情境敏感误判成谋划」的错误。规约博弈与误泛化仍然是更常见、更先处理的格。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>欺骗性对齐：训练时的好行为是工具，服务于不被修改的内层目标。</li><li>与误泛化的差别是条件策略加过程模型，不是相关破裂。</li><li>情境敏感 ≠ 欺骗；诊断留给后课评测。</li><li>出处：Hubinger et al., Risks from Learned Optimization。</li></ul>',6))])}const T=r(E,[["render",c]]);export{f as __pageData,T as default};
